html,
body,
#root {
    height: 100%;
    margin: 0;
}

.visually-hidden {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip: rect(0 0 0 0);
    white-space: nowrap;
}

/* ------------------------------------------------------------ layout */

.layout {
    display: flex;
    height: 100%;
    background: var(--g-color-base-background);
}

.layout__main {
    flex: 1;
    min-width: 0;
    overflow: hidden;
}

/* ------------------------------------------------------------ sidebar */

.sidebar {
    --sidebar-width: 232px;
    --sidebar-item-height: 36px;

    display: flex;
    flex-direction: column;
    flex-shrink: 0;
    width: var(--sidebar-width);
    padding: 12px 8px;
    box-sizing: border-box;
    overflow: hidden;
    background: var(--g-color-base-generic-ultralight);
    border-right: 1px solid var(--g-color-line-generic);
    transition: width 0.18s ease;
}

.sidebar_collapsed {
    --sidebar-width: 56px;
}

@media (prefers-reduced-motion: reduce) {
    .sidebar {
        transition: none;
    }
}

.sidebar__brand {
    display: flex;
    align-items: center;
    gap: 10px;
    height: 40px;
    padding: 0 6px;
    margin-bottom: 12px;
}

.sidebar__logo {
    display: grid;
    flex-shrink: 0;
    place-items: center;
    width: 28px;
    height: 28px;
    border-radius: var(--g-border-radius-m);
    background: var(--g-color-base-brand);
    color: var(--g-color-text-brand-contrast);
    font-weight: 600;
}

.sidebar__brand-name {
    font-weight: 600;
    font-size: 15px;
}

.sidebar__nav {
    flex: 1;
}

.sidebar__list {
    display: flex;
    flex-direction: column;
    gap: 2px;
    margin: 0;
    padding: 0;
    list-style: none;
}

.sidebar__item {
    display: flex;
    align-items: center;
    gap: 10px;
    width: 100%;
    height: var(--sidebar-item-height);
    padding: 0 10px;
    box-sizing: border-box;
    border: 0;
    border-radius: var(--g-border-radius-m);
    background: none;
    color: var(--g-color-text-primary);
    font: inherit;
    text-decoration: none;
    white-space: nowrap;
    cursor: pointer;
}

.sidebar__item:hover {
    background: var(--g-color-base-simple-hover);
}

.sidebar__item:focus-visible {
    outline: 2px solid var(--g-color-line-focus);
    outline-offset: -2px;
}

.sidebar__item_active,
.sidebar__item_active:hover {
    background: var(--g-color-base-selection);
    color: var(--g-color-text-brand);
    font-weight: 500;
}

.sidebar__icon {
    position: relative;
    display: flex;
    flex-shrink: 0;
